INSERT INTO `cpg11d_categories` (`cid`,`owner_id`,`name`,`description`,`pos`,`parent`,`thumb`,`subcat_count`,`alb_count`,`pic_count`,`stat_uptodate`) VALUES (1,0,'bitPimps Crew Galleries','Check out what some of the top bitPimp modders are producing and displaying in their own galleries!',0,0,0,0,0,0,'NO'),(2,0,'bitPimps Chop-Shop','Custom modified sleds come from pimps all around the world - and here\'s where they showcase their fine works and prove they gots the skills to pay da bills.',2,0,0,0,0,0,'NO'),(3,0,'bitPimps Ghetto Tracks','Check out the ghetto fabulous track the bitPimps built to get their race on as well as some of the tracks other pimps race on!',4,0,0,0,0,0,'NO'),(4,0,'bitPimps Contest Galleries','The bitPimps have run some of the largest micro r/c contests in the world, and we have the entries to prove it! Check out what other pimps from all over the world make when their up against fellow pimps ready to show their skills and win the bills.',3,0,0,0,0,0,'NO'),(5,0,'bitPimps Theatre','Check out some of the more entertaining videos from the sick and twisted minds behind bitPimps!',1,0,0,0,0,0,'NO');
INSERT INTO `cpg11d_comments` (`pid`,`msg_id`,`msg_author`,`msg_body`,`msg_date`,`msg_raw_ip`,`msg_hdr_ip`,`author_md5_id`,`author_id`) VALUES (211,1,'DarkTari','Slammin Azz Ride !   8-)','2004-01-27 10:34:32','134.67.6.44','161.80.224.51','',5),(45,2,'bitPimps','Cabo\'s first bit stunt. Now known as &quot;The Little Napkin Fire of Hell&quot; thanks to Namuna! :lol:','2004-01-27 10:46:02','64.240.24.194','64.240.24.194','',1),(958,38,'crazydave','That is slick!','2004-02-18 19:16:06','68.3.175.186','68.3.175.186','',7),(958,37,'hue35','sweet!','2004-02-18 17:18:40','64.122.10.46','64.122.10.46','',10),(673,32,'ph2t','This beast is mad dude!   ph2t','2004-02-12 17:06:04','203.26.37.35','203.26.37.35','',11),(1642,51,'Finks','Who ever gave this ride a sub 5 can lick my nuts :-x','2004-08-15 18:38:38','207.5.228.204','207.5.228.204','',9),(912,34,'DarkTari','Sweet Ride if I must say so myself ! 8-)','2004-02-16 01:12:04','67.27.78.72','67.27.78.72','',5),(1683,48,'sg219','Finally another boat entry!! :-D','2004-06-29 00:26:08','69.166.161.179','69.166.161.179','',36),(977,40,'bitPimps','you\'re the first to have one here - I can\'t believe you beat out Ahh5hit! :lol:','2004-02-19 17:22:14','68.184.211.201','68.184.211.201','',1);
