INSERT INTO `cpg11d_pictures` (`pid`,`aid`,`filepath`,`filename`,`filesize`,`total_filesize`,`pwidth`,`pheight`,`hits`,`mtime`,`ctime`,`owner_id`,`owner_name`,`pic_rating`,`votes`,`title`,`caption`,`keywords`,`approved`,`user1`,`user2`,`user3`,`user4`,`url_prefix`,`randpos`,`pic_raw_ip`,`pic_hdr_ip`,`lasthit_ip`) VALUES (799,38,'userpics/10008/','gtrr34_silver_fade_01.jpg',15693,20028,300,200,25,20060322083503,1076788785,0,'CaboWabo',0,0,'GTR R34 Skyline Fade','This was my 2nd or 3rd paint job.','CaboWabo GTR R34 Skyline Fade','YES','','','','',0,22,'68.184.211.201','68.184.211.201',NULL),(1899,59,'userpics/10009/','FirebirdFront.jpg',34107,38191,450,336,31,20060322083503,1089353420,9,'Finks',0,0,'Trans Am Back','This is a replica of my neighbors Trans Am.  Had to shave down the front end considerably and putty the hell outta the back.  He has some touch up paint from Pontiac that I will use when she is ready.  I dislike American cars, but this little mother just inspired me.','','YES','','','','',0,28,'207.5.159.253','207.5.159.253',NULL),(825,180,'userpics/10008/','beetle_bitpimps_04.jpg',39316,42782,400,480,16,20060322083503,1076790968,0,'CaboWabo',0,0,'bitPimps VW Beetle','I added the bitPimps logo to the hood.','CaboWabo bitPimps VW Beetle Controller','YES','','','','',0,10,'68.184.211.201','68.184.211.201',NULL);
