INSERT INTO `cpg11d_pictures` (`pid`,`aid`,`filepath`,`filename`,`filesize`,`total_filesize`,`pwidth`,`pheight`,`hits`,`mtime`,`ctime`,`owner_id`,`owner_name`,`pic_rating`,`votes`,`title`,`caption`,`keywords`,`approved`,`user1`,`user2`,`user3`,`user4`,`url_prefix`,`randpos`,`pic_raw_ip`,`pic_hdr_ip`,`lasthit_ip`) VALUES (694,294,'userpics/10001/','hue35_p3.jpg',22860,28859,300,166,363,20060322083503,1076477372,0,'bitPimps',10000,1,'Goin\' to the track to kick some ass...','[b][i]continued...[/i][/b] FETs, KIT Racer gears, 4.2 motor, finely-tuned front springs, super-low center of gravity... it\'s my favorite car to drive.','hue35 porsche fet kit racer springs','YES','','','','',0,7,'68.184.211.201','68.184.211.201',NULL),(695,294,'userpics/10001/','hue35_p4.jpg',19376,23417,300,194,364,20060322083503,1076477408,0,'bitPimps',0,0,'Goin\' to the track to kick some ass...','[b][i]continued...[/i][/b] So, instead of making it look like a brand new race car, I decided to make it look like it had a couple of ass-kicking seasons of racing under its belt.','hue35 porsche fet kit racer springs','YES','','','','',0,15,'68.184.211.201','68.184.211.201',NULL),(697,31,'userpics/10010/','kit2.jpg',15739,18999,300,225,19,20060322083503,1076480916,10,'hue35',0,0,'','','','YES','','','','',0,23,'165.121.37.106','165.121.37.106',NULL);
INSERT INTO `cpg11d_pictures` (`pid`,`aid`,`filepath`,`filename`,`filesize`,`total_filesize`,`pwidth`,`pheight`,`hits`,`mtime`,`ctime`,`owner_id`,`owner_name`,`pic_rating`,`votes`,`title`,`caption`,`keywords`,`approved`,`user1`,`user2`,`user3`,`user4`,`url_prefix`,`randpos`,`pic_raw_ip`,`pic_hdr_ip`,`lasthit_ip`) VALUES (698,31,'userpics/10010/','kit3.jpg',20880,25287,300,225,24,20060322083503,1076480958,10,'hue35',0,0,'','','','YES','','','','',0,7,'165.121.37.106','165.121.37.106',NULL),(699,31,'userpics/10010/','kit4.jpg',32663,38140,300,225,32,20060322083503,1076480999,10,'hue35',0,0,'','','','YES','','','','',0,28,'165.121.37.106','165.121.37.106',NULL),(700,31,'userpics/10010/','nsx.jpg',22366,25707,400,300,34,20060322083503,1076481302,10,'hue35',0,0,'Le Mans NSX...','This was my first TOMY car... Auto Modellista 2-speed chassis with the Mobil1 NSX body. I couldn\'t resist making it look like it had been driven hard. SuperFly\'s is still new lookin\'... still one of our best pairs of cars we race.','','YES','','','','',0,26,'165.121.37.106','165.121.37.106',NULL),(701,31,'userpics/10010/','rx7.jpg',27931,31940,400,300,36,20060322083503,1076481474,10,'hue35',0,0,'My first dual cell car...','A MicroSizers Pro with some vinyl stripes. For a long time, this was my best car... it\'s still right up there. Dual-celled cars kick ass!','','YES','','','','',0,12,'165.121.37.106','165.121.37.106',NULL);
INSERT INTO `cpg11d_pictures` (`pid`,`aid`,`filepath`,`filename`,`filesize`,`total_filesize`,`pwidth`,`pheight`,`hits`,`mtime`,`ctime`,`owner_id`,`owner_name`,`pic_rating`,`votes`,`title`,`caption`,`keywords`,`approved`,`user1`,`user2`,`user3`,`user4`,`url_prefix`,`randpos`,`pic_raw_ip`,`pic_hdr_ip`,`lasthit_ip`) VALUES (739,33,'userpics/10008/','s2k_blue_fade_04.jpg',32539,36765,400,350,33,20060322083503,1076648762,0,'CaboWabo',10000,1,'Daily Special - Track Car 2.0','Coat of dark metallic blue.','CaboWabo Daily Special - Track Car 2.0','YES','','','','',0,16,'68.184.211.201','68.184.211.201',NULL),(981,42,'userpics/10013/','DSC00123.jpg',47697,51192,800,600,62,20060322083503,1077260061,13,'YAGBOLS',10000,1,'DATSUN 510','','','YES','','','','',0,9,'203.131.103.167','203.131.103.167',NULL),(703,31,'userpics/10010/','z350.jpg',23694,27551,400,275,30,20060322083503,1076482353,10,'hue35',0,0,'My second dual cell...','Also a MicroSizers Pro. This was a cleaner job on the internal dual cell, and this car features my first &quot;HogAxle&quot;... epoxy that axle right in place. Orange gears and dual cells make for a fun amount of torque. This car literally whips around the track.','','YES','','','','',0,30,'165.121.37.106','165.121.37.106',NULL),(704,294,'userpics/10001/','crazydave_beetle_vdm01.jpg',23348,26901,400,322,264,20060322083503,1076620744,0,'bitPimps',10000,1,'Sick Green Flames','[b][i]crazydave writes:[/i][/b] I was doing some mods for VDM, and he\'s hooking me up. So I wanted to give him a little something extra. So I offered to flame out his LXX Beetle. He wasn\'t saying no.\r\n\r\nSo here\'s you car now VDM. :)','crazydave beetle flames','YES','','','','',0,25,'68.184.211.201','68.184.211.201',NULL);
INSERT INTO `cpg11d_pictures` (`pid`,`aid`,`filepath`,`filename`,`filesize`,`total_filesize`,`pwidth`,`pheight`,`hits`,`mtime`,`ctime`,`owner_id`,`owner_name`,`pic_rating`,`votes`,`title`,`caption`,`keywords`,`approved`,`user1`,`user2`,`user3`,`user4`,`url_prefix`,`randpos`,`pic_raw_ip`,`pic_hdr_ip`,`lasthit_ip`) VALUES (705,294,'userpics/10001/','crazydave_beetle_vdm02.jpg',16981,21349,400,246,263,20060322083503,1076620803,0,'bitPimps',0,0,'Sick Green Flames','[b][i]continued...[/i][/b] I liked the sick green the car came in, but alot of the LXX paint mask were put on crooked. I thought I could keep the green, and clean up the areas where the paint mask had been crooked. I faded some Aqua in the front, and layed Charcoal over the rest.','crazydave beetle flames','YES','','','','',0,6,'68.184.211.201','68.184.211.201',NULL),(706,294,'userpics/10001/','crazydave_beetle_vdm03.jpg',16852,20566,400,265,249,20060322083503,1076620848,0,'bitPimps',10000,1,'Sick Green Flames','[b][i]continued...[/i][/b] Pics do not do this job justice. The flash makes the Aqua blend into the green to much, and you can\'t really see how smooth the fade really looks. This shade of charcoal always looks black in pics, but really it\'s a dark metallic grey. I would have spent half the day trying to get the pictures just right, but in this case I knew VDM was going to be able vouch for it when he got it.\r\n\r\nSo here it is...Hope you like it VDM. I\'m proud of it.','crazydave beetle flames','YES','','','','',0,19,'68.184.211.201','68.184.211.201',NULL),(707,32,'userpics/10011/','contest1.JPG',42610,91018,673,505,34,20060322083503,1076624165,11,'ph2t',0,0,'KnightRider','Still my favorite bit to date.  2nd place in the Bitpimps Twisted Plastic comp.','','YES','','','','',0,14,'203.26.37.35','203.26.37.35',NULL);
