INSERT INTO `cpg11d_pictures` (`pid`,`aid`,`filepath`,`filename`,`filesize`,`total_filesize`,`pwidth`,`pheight`,`hits`,`mtime`,`ctime`,`owner_id`,`owner_name`,`pic_rating`,`votes`,`title`,`caption`,`keywords`,`approved`,`user1`,`user2`,`user3`,`user4`,`url_prefix`,`randpos`,`pic_raw_ip`,`pic_hdr_ip`,`lasthit_ip`) VALUES (1112,157,'userpics/10001/','2.jpg',21669,24770,387,337,19,20060322083503,1080273285,0,'bitPimps',0,0,'Scene 2','&quot;After being roused from my daily, um, er, karate class\r\nby the secret service...&quot;','','YES','','','','',0,5,'68.184.211.201','68.184.211.201',NULL),(1107,56,'userpics/10028/','Track2~0.jpg',50742,55254,400,225,35,20060322083503,1080150173,28,'ripper7777777',0,0,'Battling Skylines','This is a pic of 2 Epoch Skylines I did for a customer.  It gives a good size compatison of the details on the track.','','YES','','','','',0,14,'24.242.228.211','24.242.228.211',NULL),(1108,56,'userpics/10028/','track3.jpg',78435,82287,400,300,26,20060322083503,1080150238,28,'ripper7777777',0,0,'Pit Area','A detailed view of the pit area and the fence behind it.','','YES','','','','',0,22,'24.242.228.211','24.242.228.211',NULL),(1105,56,'userpics/10028/','Track1.jpg',66117,70167,400,271,36,20060322083503,1080150032,28,'ripper7777777',0,0,'Micro RC Grand Raceway 2','This Track replaced the Original Micro RC Grand Raceway. When I stepped up into the epoch realm I needed a little more space. This track is also great for dual cell ZZ\'s and Bits, plenty of room to test the throttle. The track itself folds back up on to the table and the Overall Dims are 8\'x7\' and the average lane width is 12&quot;. I hated destroying the other track but once this one was complete, I quickly forgot the old track.','','YES','','','','',0,4,'24.242.228.211','24.242.228.211',NULL);
INSERT INTO `cpg11d_pictures` (`pid`,`aid`,`filepath`,`filename`,`filesize`,`total_filesize`,`pwidth`,`pheight`,`hits`,`mtime`,`ctime`,`owner_id`,`owner_name`,`pic_rating`,`votes`,`title`,`caption`,`keywords`,`approved`,`user1`,`user2`,`user3`,`user4`,`url_prefix`,`randpos`,`pic_raw_ip`,`pic_hdr_ip`,`lasthit_ip`) VALUES (1110,56,'userpics/10028/','Track4.jpg',57177,60518,400,300,22,20060322083503,1080151196,28,'ripper7777777',0,0,'Just another pic','One last Detail shot.\r\nYou can see more pics at my Home page - http://home.houston.rr.com/extremedesigns/','','YES','','','','',0,17,'24.242.228.211','24.242.228.211',NULL),(1113,157,'userpics/10001/','3.jpg',33356,42334,400,189,20,20060322083503,1080273318,0,'bitPimps',0,0,'Scene 3','&quot;I was informed that the notorious &quot;bitPimps&quot; syndicate was attempting to overthrow the state of Pimpafornia by massing at the state assembly building.&quot;\r\n\r\n&quot;I got to flyin\' in my Air Force One immediately, to assist the governor of Pimpafornia, Aahnold SportsnJager, at the assembly.&quot;','','YES','','','','',0,12,'68.184.211.201','68.184.211.201',NULL),(1114,157,'userpics/10001/','4.jpg',13827,18353,400,174,6,20060321083112,1080273379,0,'bitPimps',0,0,'Scene 4','&quot;Ya, deez peemps vill not be staging any coup in de state of Peempaahfohnia vile Ah\'m de guuvuhnaaah&quot;( cheesy Austrian accent) \r\n\r\n&quot;We will now send in the P.C.P.D to attempt to negotiate with the ringleaders&quot;.','','YES','','','','',0,9,'68.184.211.201','68.184.211.201',NULL);
INSERT INTO `cpg11d_pictures` (`pid`,`aid`,`filepath`,`filename`,`filesize`,`total_filesize`,`pwidth`,`pheight`,`hits`,`mtime`,`ctime`,`owner_id`,`owner_name`,`pic_rating`,`votes`,`title`,`caption`,`keywords`,`approved`,`user1`,`user2`,`user3`,`user4`,`url_prefix`,`randpos`,`pic_raw_ip`,`pic_hdr_ip`,`lasthit_ip`) VALUES (1115,157,'userpics/10001/','5.jpg',43083,49044,400,300,11,20060321083112,1080273653,0,'bitPimps',0,0,'Scene 5','&quot;Um, fellas, uh, you think you can disperse immediately? The president and the governor are trying to avoid a confrontation... plus they\'re punks...&quot; \r\n\r\n&quot;Oh hell no! Tell those fools they gotta come tell us to our face!&quot;\r\n\r\n&quot;Ok, fellas... calm down... Can I offer you one of these here tasty donuts?&quot;','','YES','','','','',0,9,'68.184.211.201','68.184.211.201',NULL),(1116,157,'userpics/10001/','7.jpg',13827,18353,400,174,8,20060322083503,1080273735,0,'bitPimps',0,0,'Scene 7','&quot;So, as you can see, or not, due to the mysterious disappearance of pic #6(dammit!), that governor SportsnJager and myself were accosted by those treacherous thugs.&quot;','','YES','','','','',0,19,'68.184.211.201','68.184.211.201',NULL),(1117,157,'userpics/10001/','8.jpg',44333,50208,400,300,12,20060322083503,1080273760,0,'bitPimps',0,0,'Scene 8','&quot;Ya, vee deed naaht know zat zey haaahd a taaaaahnk!&quot; \r\n(cheesy Austrian accent again)','','YES','','','','',0,4,'68.184.211.201','68.184.211.201',NULL);
