INSERT INTO `cpg11d_pictures` (`pid`,`aid`,`filepath`,`filename`,`filesize`,`total_filesize`,`pwidth`,`pheight`,`hits`,`mtime`,`ctime`,`owner_id`,`owner_name`,`pic_rating`,`votes`,`title`,`caption`,`keywords`,`approved`,`user1`,`user2`,`user3`,`user4`,`url_prefix`,`randpos`,`pic_raw_ip`,`pic_hdr_ip`,`lasthit_ip`) VALUES (1541,89,'userpics/10012/','lancerprojectphase3.jpg',68858,117721,640,352,29,20060322083503,1087013359,12,'betty.k',0,0,'custom tail lights','','','YES','','','','',0,29,'210.50.30.21','210.50.218.37',NULL),(1179,289,'userpics/10001/','29_geisem_2.jpg',37645,41173,600,450,253,20060322083503,1081742370,0,'bitPimps',0,0,'Geisem','11-Apr-04','','YES','','','','',0,11,'68.184.211.201','68.184.211.201',NULL),(1180,159,'userpics/10001/','01~0.jpg',100445,106407,600,450,33,20060322083503,1081743730,0,'bitPimps',0,0,'Scene 1','Well i just got the call from ph2t, he\'s coming over at lunchtime, i just gotta go pick him up from the train station. so let\'s go see a little bit of australia on the way!','','YES','','','','',0,30,'68.184.211.201','68.184.211.201',NULL),(1181,159,'userpics/10001/','02~0.jpg',79560,84654,600,450,28,20060322083503,1081743760,0,'bitPimps',0,0,'Scene 2','Crikey!! here\'s a little laser shooting ant!! lucky for me he\'s just a little feller or i\'d never make it to the car! his laser\'s really starting to hurt now and his mother could be close so we better get outta here!','','YES','','','','',0,22,'68.184.211.201','68.184.211.201',NULL);
INSERT INTO `cpg11d_pictures` (`pid`,`aid`,`filepath`,`filename`,`filesize`,`total_filesize`,`pwidth`,`pheight`,`hits`,`mtime`,`ctime`,`owner_id`,`owner_name`,`pic_rating`,`votes`,`title`,`caption`,`keywords`,`approved`,`user1`,`user2`,`user3`,`user4`,`url_prefix`,`randpos`,`pic_raw_ip`,`pic_hdr_ip`,`lasthit_ip`) VALUES (1182,159,'userpics/10001/','03~0.jpg',65751,70827,600,450,31,20060322083503,1081743791,0,'bitPimps',0,0,'Scene 3','Whooaaaa!! didn\'t see this little beauty! this is an eastern bullcrap snake (slipperius latexus). good thing for me he\'s pretty slow and only a baby. this is their way of familiarising themselves with their surroundings! i can feel his fangs piercing my lungs right now!','','YES','','','','',0,20,'68.184.211.201','68.184.211.201',NULL),(1183,159,'userpics/10001/','04~0.jpg',48127,52489,600,450,26,20060322083503,1081743826,0,'bitPimps',0,0,'Scene 4','Phew!! all that cuddlin gave me a bloody ripper of an apetite! early explorers perished in this harsh outback climate, cos they didn\'t know how to survive from the natural environment. through years of croc chasing i\'ve come to learn to recognise the signs that there\'s some good eatin\' nearby..............','','YES','','','','',0,1,'68.184.211.201','68.184.211.201',NULL),(1184,159,'userpics/10001/','05~0.jpg',88132,93169,600,450,29,20060322083503,1081743867,0,'bitPimps',0,0,'Scene 5','.....and here we go, good ol aussie tucker!! i hope they still got those grouse dingo nuggets!','','YES','','','','',0,11,'68.184.211.201','68.184.211.201',NULL);
INSERT INTO `cpg11d_pictures` (`pid`,`aid`,`filepath`,`filename`,`filesize`,`total_filesize`,`pwidth`,`pheight`,`hits`,`mtime`,`ctime`,`owner_id`,`owner_name`,`pic_rating`,`votes`,`title`,`caption`,`keywords`,`approved`,`user1`,`user2`,`user3`,`user4`,`url_prefix`,`randpos`,`pic_raw_ip`,`pic_hdr_ip`,`lasthit_ip`) VALUES (1185,159,'userpics/10001/','06~0.jpg',76458,80921,600,450,27,20060322083503,1081743900,0,'bitPimps',0,0,'Scene 6','Introduced species are a real problem in our country, and there\'s none worse than the dreaded arctic feral cat (felinus stupidicus). AAAGH! CRIKEY!!! he\'s got us! quick bruce, punch it while he\'s looking the other way!!','','YES','','','','',0,19,'68.184.211.201','68.184.211.201',NULL),(1186,159,'userpics/10001/','07~0.jpg',87621,93871,600,450,21,20060322083503,1081743934,0,'bitPimps',0,0,'Scene 7','Have a look at this little beauty! it\'s a speckled fart sucker (arachnogaseus vacumicus) i\'m not going to get too close because once they attach themselves to you they drive their foot long fangs into ya abdomen and drain your gases and inflate themselves enough to float, using the winds to carry them to more fertile feeding grounds!','','YES','','','','',0,28,'68.184.211.201','68.184.211.201',NULL),(1187,159,'userpics/10001/','08~0.jpg',71819,76790,600,450,30,20060322083503,1081743969,0,'bitPimps',0,0,'Scene 8','Struth! finally at the station. there\'s ph2t in the snacks car and hey look! there\'s bruce on his vespa! azzitgarn bruce!?','','YES','','','','',0,22,'68.184.211.201','68.184.211.201',NULL);
