INSERT INTO `cpg11d_pictures` (`pid`,`aid`,`filepath`,`filename`,`filesize`,`total_filesize`,`pwidth`,`pheight`,`hits`,`mtime`,`ctime`,`owner_id`,`owner_name`,`pic_rating`,`votes`,`title`,`caption`,`keywords`,`approved`,`user1`,`user2`,`user3`,`user4`,`url_prefix`,`randpos`,`pic_raw_ip`,`pic_hdr_ip`,`lasthit_ip`) VALUES (1223,160,'userpics/10001/','mm_06.jpg',46324,52549,500,333,38,20060322083503,1082696367,0,'bitPimps',10000,1,'Scene 6','I heard the little one, midget_man saying, &quot;What, you want some of this shit, biatch!!?? I\'ll work you, dogg!!&quot;','','YES','','','','',0,11,'24.207.244.0','24.207.244.0',NULL),(1224,160,'userpics/10001/','mm_07.jpg',45765,51996,500,333,35,20060322083503,1082696391,0,'bitPimps',10000,1,'Scene 7','I kept snapping photos, as midget_man bumrushed the man, tackling him to the ground. ','','YES','','','','',0,26,'24.207.244.0','24.207.244.0',NULL),(1225,160,'userpics/10001/','mm_08.jpg',41847,47410,500,333,36,20060322083503,1082696419,0,'bitPimps',10000,1,'Scene 8','as he was on the ground, the pair of gangsters continued &quot;whooping ass&quot;, as the bitPimps call it. The kicked and punched him as he lay helplessly on the ground. They even let their dog get in on the action.','','YES','','','','',0,2,'24.207.244.0','24.207.244.0',NULL),(1226,160,'userpics/10001/','mm_09.jpg',28978,32201,500,333,41,20060322083503,1082696451,0,'bitPimps',10000,1,'Scene 9','all of the sudden, the club owners came out of nowhere and knocked me to the ground, knocking the lens off my camera. They kicked the two men and their dog out, telling them never to come back. I fixed my camera in time to see them getting told never to return.','','YES','','','','',0,27,'24.207.244.0','24.207.244.0',NULL);
INSERT INTO `cpg11d_pictures` (`pid`,`aid`,`filepath`,`filename`,`filesize`,`total_filesize`,`pwidth`,`pheight`,`hits`,`mtime`,`ctime`,`owner_id`,`owner_name`,`pic_rating`,`votes`,`title`,`caption`,`keywords`,`approved`,`user1`,`user2`,`user3`,`user4`,`url_prefix`,`randpos`,`pic_raw_ip`,`pic_hdr_ip`,`lasthit_ip`) VALUES (1227,160,'userpics/10001/','mm_10.jpg',19212,22750,500,333,72,20060322083503,1082696485,0,'bitPimps',10000,1,'Scene 10','I was able to get one more picture, as the pimps got in their lowrider and screamed off. I was told later by the club owner that the man survived the attack, but had many cuts and bruises.','','YES','','','','',0,0,'24.207.244.0','24.207.244.0',NULL),(1229,83,'userpics/10012/','skylinepbshell.JPG',219173,281643,1280,960,29,20060322083503,1082733776,12,'betty.k',0,0,'before pic of the iwaver copy','','','YES','','','','',0,18,'210.50.30.20','210.50.44.149',NULL),(1230,150,'userpics/10031/','DCP_3729.JPG',19945,20480,500,333,35,20060322083503,1082749986,31,'midget_man1387',0,0,'project: keepin it low and slow','Here is my latest project. It is a lowrider that I had to move the idler gear because it was so low.','lowrider bB slammed','YES','','','','',0,22,'66.132.6.174','66.132.6.174',NULL),(1514,150,'userpics/10031/','DCP_0027.jpg',14911,18578,400,266,25,20060322083503,1086367925,31,'midget_man1387',0,0,'contest celica','this is a celica that I made for this contest.... I\'ve been working on it for months, but when the contest rolled around I kicked it into high gear and told myself i needed to work on this. I\'m very please with the painting... The lines on the side are hand masked, then gone over, actually dotted with black paint. that gave it the kind of &quot;ripped effect.&quot;','','YES','','','','',0,28,'67.129.200.195','67.129.200.195',NULL);
