INSERT INTO `cpg11d_pictures` (`pid`,`aid`,`filepath`,`filename`,`filesize`,`total_filesize`,`pwidth`,`pheight`,`hits`,`mtime`,`ctime`,`owner_id`,`owner_name`,`pic_rating`,`votes`,`title`,`caption`,`keywords`,`approved`,`user1`,`user2`,`user3`,`user4`,`url_prefix`,`randpos`,`pic_raw_ip`,`pic_hdr_ip`,`lasthit_ip`) VALUES (7317,333,'userpics/10049/','Group2.JPG',210887,261684,705,312,5,20060322083503,1141179088,49,'hachi-ryoku',0,0,'','','','YES','','','','',0,10,'70.174.60.46','70.174.60.46',NULL),(7322,394,'userpics/10088/','Trogdor_1.JPG',159568,195369,640,480,4,20060322083503,1141495704,88,'frizzen',0,0,'Trogdor The Burninator','This is the introduction pic to my new theme truck Trogdor the Burninator.  It is a &quot;The Hulk&quot; body, I removed it\'s tonau cover with fake rollbar coverings, replaced those with a solid rear panel and a flat tonau for extra graphics room.  49mhz chassis, chrome rims with chevrons.\r\n\r\nThis is the real Trogdor.  \r\n    http://www.homestarrunner.com/sbemail58.html','trogdor dragon hulk zz-m','YES','','','','',0,27,'69.210.4.195','69.210.4.195',NULL),(7323,394,'userpics/10088/','TheHulk.jpg',9815,12624,345,235,4,20060322083503,1141496131,88,'frizzen',0,0,'Hulking Ugly','The Hulk:  An ugly body I avoided until after it was discontinued.  At which point I came up with a better theme, and began a months long search for one. \r\n\r\nAfter a few mods, some paint, clear, decals, more clear...  It shall become Trogdor the Burninator.  ','hulk trogdor zz-m truck','YES','','','','',0,10,'69.210.4.195','69.210.4.195',NULL);
